def build_agent_command(prompt: str) -> list[str]:
    if claude_mode_enabled:
        return ["claude", "-p", prompt, "--model", CLAUDE_MODEL]
    return [
        "opencode",
        "run",
        "--print-logs",
        "--log-level",
        "ERROR",
        "--model",
        OPENCODE_MODEL,
        prompt,
    ]


def ask_use_claude() -> bool:
    if not wants_resume(input("Use claude instead of opencode? [y/N] ")):
        return False
    if not wants_resume(input("Are you signed in to claude? [y/N] ")):
        print("sign in with `claude` first, falling back to opencode")
        return False
    if not wants_resume(input("Are you sure? It will use Fable 5, very expensive. [y/N] ")):
        return False
    return True


def run_opencode(prompt: str, log_name: str) -> tuple[int, str, int | None]:
    LOGS_DIR.mkdir(parents=True, exist_ok=True)
    command = build_agent_command(prompt)
